package com.abosultan.darbakmaps.ui;

import android.app.Activity;import android.app.AlertDialog;import android.content.Context;import android.content.pm.PackageInfo;import android.graphics.Color;import android.graphics.drawable.ColorDrawable;import android.graphics.Typeface;import android.view.Gravity;import android.view.View;import android.view.Window;import android.widget.ImageView;import android.widget.LinearLayout;import android.widget.TextView;import android.widget.Toast;
import com.abosultan.darbakmaps.R;import com.abosultan.darbakmaps.core.CoreContracts.LocationSnapshot;import com.abosultan.darbakmaps.core.LiveLocationStore;import com.abosultan.darbakmaps.core.SessionStore;import com.abosultan.darbakmaps.core.SqliteTrackRecorder;import com.abosultan.darbakmaps.update.UpdateManager;import java.io.File;
final class MoreDialog {
 static void show(Context c,OfflineMapView map){SessionStore session=new SessionStore(c);boolean autoLaunch=session.shouldAutoLaunch();LocationSnapshot fix=LiveLocationStore.latest();String mapName=map.activeMapName();String status="الإصدار  "+versionName(c)+"\nالخريطة  "+(mapName==null?"غير جاهزة":mapName)+"\nGPS  "+(fix.valid?"متصل":"بانتظار الإشارة")+"\nتسجيل المسار  "+(session.shouldResumeTrackRecording()?"يعمل":"متوقف مؤقتًا");LinearLayout box=panel(c,"المزيد");TextView sv=bodyText(c,status,16,false);sv.setBackground(DarbakUi.rounded(DarbakUi.CARD,DarbakUi.BORDER,14,c));sv.setPadding(DarbakUi.dp(c,18),DarbakUi.dp(c,12),DarbakUi.dp(c,18),DarbakUi.dp(c,12));box.addView(sv,matchWrap(c,0));final AlertDialog[] h=new AlertDialog[1];addAction(c,box,"الإعدادات",v->{if(h[0]!=null)h[0].dismiss();SettingsDialog.show(c);});addAction(c,box,"فحص التحديث",v->{if(h[0]!=null)h[0].dismiss();checkUpdate(c);});addAction(c,box,"حول دربك للخرائط",v->{if(h[0]!=null)h[0].dismiss();showAbout(c);});addAction(c,box,autoLaunch?"إيقاف التشغيل التلقائي":"تفعيل التشغيل التلقائي",v->{boolean next=!autoLaunch;session.setAutoLaunch(next);if(next){try{c.startService(new android.content.Intent(c,com.abosultan.darbakmaps.core.TrackRecordingService.class));}catch(RuntimeException ignored){}}Toast.makeText(c,next?"تم تفعيل التشغيل التلقائي":"تم إيقاف التشغيل التلقائي",Toast.LENGTH_SHORT).show();if(h[0]!=null)h[0].dismiss();});addAction(c,box,"تمركز على السيارة",v->{if(!map.recenterOnGps())Toast.makeText(c,map.hasMap()?"بانتظار إشارة GPS":"الخريطة غير جاهزة",Toast.LENGTH_SHORT).show();if(h[0]!=null)h[0].dismiss();});addSecondary(c,box,"إغلاق",v->{if(h[0]!=null)h[0].dismiss();});h[0]=showPanel(c,box);}
 static void showDiagnostics(Context c,OfflineMapView map){LocationSnapshot fix=LiveLocationStore.latest();File db=c.getDatabasePath("darbak_tracks.db");SqliteTrackRecorder r=new SqliteTrackRecorder(c);double retained;try{retained=r.retainedDistanceMeters();}finally{r.close();}long age=fix.valid?Math.max(0L,System.currentTimeMillis()-fix.timestampMs):-1L;String text="الحزمة  "+c.getPackageName()+"\nالإصدار  "+versionName(c)+"\nالخريطة  "+(map.activeMapName()==null?"غير جاهزة":map.activeMapName())+"\nGPS age  "+(age<0?"—":age+" ms")+"\nالمسار الدائري  "+Math.round(retained/1000d)+" كم\nقاعدة المسار  "+(db!=null&&db.isFile()?db.length()/1024+" KB":"—")+"\nAndroid API  "+android.os.Build.VERSION.SDK_INT;LinearLayout box=panel(c,"تشخيص دربك");box.addView(bodyText(c,text,16,false),matchWrap(c,0));final AlertDialog[] h=new AlertDialog[1];addSecondary(c,box,"إغلاق",v->{if(h[0]!=null)h[0].dismiss();});h[0]=showPanel(c,box);}
 private static void checkUpdate(Context c){if(!(c instanceof Activity)){Toast.makeText(c,"تعذر فتح التحديث",Toast.LENGTH_SHORT).show();return;}Activity a=(Activity)c;Toast.makeText(c,"جارٍ فحص التحديث…",Toast.LENGTH_SHORT).show();UpdateManager.check(new UpdateManager.Callback(){@Override public void onStatus(String m){a.runOnUiThread(()->Toast.makeText(a,m,Toast.LENGTH_LONG).show());}@Override public void onUpdate(UpdateManager.UpdateInfo u){a.runOnUiThread(()->showUpdateAvailable(a,u,this));}});}
 private static void showUpdateAvailable(Activity a,UpdateManager.UpdateInfo u,UpdateManager.Callback cb){LinearLayout box=panel(a,"تحديث متاح — "+u.versionName);box.addView(bodyText(a,"سيتم تنزيل النسخة والتحقق من سلامتها وتوقيعها قبل فتح مثبت النظام.",16,false),matchWrap(a,0));final AlertDialog[] h=new AlertDialog[1];addAction(a,box,"تنزيل وتثبيت",v->{if(h[0]!=null)h[0].dismiss();UpdateManager.downloadAndInstall(a,u,cb);});addSecondary(a,box,"لاحقًا",v->{if(h[0]!=null)h[0].dismiss();});h[0]=showPanel(a,box);}
 private static void showAbout(Context c){LinearLayout box=panel(c,"حول دربك للخرائط");TextView t=bodyText(c,"دربك للخرائط\nالإصدار "+versionName(c)+"\nخرائط بر أوفلاين — Android 7.1 / 1024×600",17,true);t.setGravity(Gravity.CENTER);box.addView(t,matchWrap(c,0));ImageView s=new ImageView(c);s.setImageResource(R.drawable.darbak_owner_signature);s.setAdjustViewBounds(true);s.setScaleType(ImageView.ScaleType.FIT_CENTER);s.setBackgroundColor(Color.TRANSPARENT);LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(-1,DarbakUi.dp(c,130));ip.topMargin=DarbakUi.dp(c,8);box.addView(s,ip);final AlertDialog[] h=new AlertDialog[1];addSecondary(c,box,"إغلاق",v->{if(h[0]!=null)h[0].dismiss();});h[0]=showPanel(c,box);}
 private static LinearLayout panel(Context c,String title){LinearLayout b=new LinearLayout(c);b.setOrientation(LinearLayout.VERTICAL);b.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);int p=DarbakUi.dp(c,18);b.setPadding(p,p,p,p);b.setBackground(DarbakUi.rounded(DarbakUi.BG,DarbakUi.ACCENT,20,c));TextView t=bodyText(c,title,21,true);t.setTextColor(DarbakUi.ACCENT);b.addView(t,matchWrap(c,0));return b;}private static TextView bodyText(Context c,String v,int sp,boolean bold){TextView t=new TextView(c);t.setText(v);t.setTextColor(DarbakUi.TEXT);t.setTextSize(sp);t.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private static void addAction(Context c,LinearLayout b,String l,View.OnClickListener x){TextView a=DarbakUi.action(c,l);a.setOnClickListener(x);LinearLayout.LayoutParams p=matchWrap(c,8);p.height=DarbakUi.dp(c,50);b.addView(a,p);}private static void addSecondary(Context c,LinearLayout b,String l,View.OnClickListener x){TextView a=DarbakUi.action(c,l);a.setTextColor(DarbakUi.TEXT_SECONDARY);a.setOnClickListener(x);LinearLayout.LayoutParams p=matchWrap(c,8);p.height=DarbakUi.dp(c,46);b.addView(a,p);}private static LinearLayout.LayoutParams matchWrap(Context c,int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=DarbakUi.dp(c,top);return p;}private static AlertDialog showPanel(Context c,LinearLayout b){AlertDialog d=new AlertDialog.Builder(c).setView(b).create();d.setOnShowListener(x->{Window w=d.getWindow();if(w!=null){w.setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));w.setDimAmount(.55f);}});d.show();return d;}private static String versionName(Context c){try{PackageInfo i=c.getPackageManager().getPackageInfo(c.getPackageName(),0);return i.versionName==null?"—":i.versionName;}catch(Exception e){return"—";}}private MoreDialog(){}
}
